<template><div class="page"><div class="page-header"><div><el-button link @click="router.push('/chapters')"><ArrowLeft/>章节管理</el-button><h1 class="page-title">知识点管理</h1><p class="page-description">知识点用于精准检索、出题筛选和试卷覆盖分析。</p></div><el-button type="primary" @click="open()"><Plus/>新增知识点</el-button></div><div class="toolbar card card-body"><el-select v-model="filters.course" placeholder="选择课程" style="width:230px"><el-option v-for="c in store.courses" :key="c.id" :label="c.name" :value="c.id"/></el-select><el-input v-model="filters.keyword" placeholder="搜索知识点" style="width:220px"/><el-select v-model="aiFile" placeholder="选择文件AI提取" clearable style="width:250px"><el-option v-for="f in files" :key="f.id" :label="f.original_name" :value="f.id"/></el-select><el-button @click="load">查询</el-button><el-button :loading="extracting" :disabled="!aiFile" @click="extract"><MagicStick/>AI提取知识点</el-button></div><div class="card"><PageState :loading="loading" :empty="!items.length" empty-text="当前条件下没有知识点。"><el-table :data="items"><el-table-column prop="name" label="知识点名称" min-width="180"/><el-table-column prop="course_name" label="课程" width="150"/><el-table-column prop="chapter_name" label="章节" width="180"/><el-table-column label="关键词" min-width="180"><template #default="s"><el-tag v-for="k in s.row.keywords" :key="k" size="small" style="margin-right:4px">{{k}}</el-tag></template></el-table-column><el-table-column prop="importance" label="重要程度" width="90"/><el-table-column prop="difficulty" label="难度" width="80"/><el-table-column prop="question_count" label="题目数" width="80"/><el-table-column label="操作" width="130"><template #default="s"><el-button link @click="open(s.row)">编辑</el-button><el-button link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table></PageState></div><el-dialog v-model="dialog" :title="form.id?'编辑知识点':'新增知识点'" width="620"><el-form :model="form" label-width="90px"><el-form-item label="名称" required><el-input v-model="form.name"/></el-form-item><el-form-item label="所属章节"><el-select v-model="form.chapter" clearable style="width:100%"><el-option v-for="c in flatChapters" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item label="知识说明"><el-input v-model="form.description" type="textarea" :rows="3"/></el-form-item><el-form-item label="关键词"><el-select v-model="form.keywords" multiple filterable allow-create default-first-option style="width:100%"/></el-form-item><div class="form-grid"><el-form-item label="重要程度"><el-select v-model="form.importance"><el-option v-for="x in ['一般','重要','核心']" :key="x" :label="x" :value="x"/></el-select></el-form-item><el-form-item label="难度"><el-select v-model="form.difficulty"><el-option v-for="x in ['简单','较易','中等','较难','困难']" :key="x" :label="x" :value="x"/></el-select></el-form-item></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog><el-dialog v-model="previewDialog" title="AI知识点提取预览" width="800"><el-table :data="preview.knowledge_points||[]" max-height="430"><el-table-column prop="name" label="名称"/><el-table-column prop="chapter_name" label="章节"/><el-table-column prop="importance" label="重要程度" width="90"/><el-table-column prop="difficulty" label="难度" width="80"/></el-table><template #footer><el-button @click="previewDialog=false">取消</el-button><el-button type="primary" @click="confirmImport">确认导入</el-button></template></el-dialog></div></template>
<script setup>import{ref,reactive,watch,onMounted}from'vue';import{useRouter}from'vue-router';import{ElMessage,ElMessageBox}from'element-plus';import{knowledgeApi}from'../../api';import{useAppStore}from'../../stores/app';import PageState from'../../components/PageState.vue';const router=useRouter(),store=useAppStore(),items=ref([]),files=ref([]),flatChapters=ref([]),loading=ref(false),dialog=ref(false),aiFile=ref(''),extracting=ref(false),preview=ref({}),previewId=ref(null),previewDialog=ref(false),filters=reactive({course:'',keyword:''}),form=reactive({id:null,course:null,chapter:null,name:'',description:'',keywords:[],importance:'重要',difficulty:'中等',source_type:'MANUAL'});const flatten=x=>x.flatMap(n=>[n,...flatten(n.children||[])]);const load=async()=>{if(!filters.course)return;loading.value=true;try{const[d,f,c]=await Promise.all([knowledgeApi.points({...filters,page_size:100}),knowledgeApi.files({course:filters.course,status:'SUCCESS',page_size:100}),knowledgeApi.chapters({course:filters.course})]);items.value=d.items;files.value=f.items;flatChapters.value=flatten(c)}finally{loading.value=false}};watch(()=>filters.course,load);const open=x=>{Object.assign(form,{id:null,course:filters.course,chapter:null,name:'',description:'',keywords:[],importance:'重要',difficulty:'中等',source_type:'MANUAL'},x||{});dialog.value=true};const save=async()=>{if(!form.name.trim())return ElMessage.warning('请输入知识点名称');form.id?await knowledgeApi.updatePoint(form.id,form):await knowledgeApi.createPoint(form);dialog.value=false;ElMessage.success('知识点已保存');load()};const remove=async x=>{await ElMessageBox.confirm(`确认删除“${x.name}”？`,'删除知识点',{type:'warning'});await knowledgeApi.deletePoint(x.id);load()};const extract=async()=>{extracting.value=true;try{const d=await knowledgeApi.aiPoints({file_id:aiFile.value});preview.value=d.result;previewId.value=d.preview_id;previewDialog.value=true}finally{extracting.value=false}};const confirmImport=async()=>{await knowledgeApi.confirmPoints({preview_id:previewId.value});previewDialog.value=false;ElMessage.success('知识点已导入');load()};onMounted(async()=>{await store.loadCourses();filters.course=store.courses[0]?.id||''})</script>
